#include <vector>
#include <iostream>

int main() {
    std::vector<int> v{1, 2, 3, 4, 5, 6};
    for (auto it = v.begin(); it != v.end(); ) {
        if (*it % 2 == 0)
            it = v.erase(it);   // erase returns the next valid iterator
        else
            ++it;
    }
    for (int x : v) std::cout << x << " ";
    std::cout << "\n";
}

#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<int> v{5, 9, 2, 9, 7, 9};
    auto newEnd = std::remove(v.begin(), v.end(), 9);
    std::cout << "size still " << v.size() << "\n";   // 6: remove never erases
    v.erase(newEnd, v.end());
    std::cout << "size now " << v.size() << "\n";     // 3
}

#include <vector>
#include <algorithm>
#include <iostream>

int main() {
    std::vector<double> px{100.50, 99.75, 101.00, 100.50};
    std::sort(px.begin(), px.end());
    // sorted: 99.75  100.50  100.50  101.00
    auto lo = std::lower_bound(px.begin(), px.end(), 100.50);
    std::cout << lo - px.begin() << "\n";          // first position >= 100.50
    auto up = std::upper_bound(px.begin(), px.end(), 100.50);
    std::cout << up - px.begin() << "\n";          // first position > 100.50
    std::cout << std::boolalpha
              << std::binary_search(px.begin(), px.end(), 101.00) << "\n";
}

#include <vector>
#include <numeric>
#include <iostream>

int main() {
    std::vector<int> fills{150, 200, 100};
    int total = std::accumulate(fills.begin(), fills.end(), 0);
    std::cout << "filled " << total << "\n";            // 450

    std::vector<double> rets{0.01, -0.02, 0.03};
    // int init: every partial sum is truncated to an integer
    int truncated = std::accumulate(rets.begin(), rets.end(), 0);
    std::cout << "int init gives " << truncated << "\n";  // 0
}

